// The chinese calendar: ICU's month table for related ISO years -6000..2200 (calendar_chinese_data.inc, generated by
// tools/temporal/gen-calendars.mjs), mean lunations outside it.
#include "builtins/temporal/calendar_lunisolar.h"

namespace snowman::temporal {

namespace {
#include "builtins/temporal/calendar_chinese_data.inc"

const LunisolarTableCalendar kChinese({kChineseFirstYear, kChineseFirstNewYear, kChineseYears});
static_assert(sizeof(kChineseYears) / sizeof(kChineseYears[0]) == size_t(kChineseLastYear - kChineseFirstYear + 1));
}  // namespace

const CalendarSystem* ChineseCalendarSystem() { return &kChinese; }

}  // namespace snowman::temporal
